                    position={[0, -0.01, 0]} 
                    onClick={tool !== ToolType.SELECT && tool !== ToolType.PUSH_PULL ? drawHandleClick : undefined}
                    onPointerDown={drawHandlePointerDown}
                    onPointerUp={(e) => {
                        drawHandlePointerUp(e);
                        ppHandlePointerUp(); 
                    }}
                    onPointerMove={tool === ToolType.PUSH_PULL ? ppHandlePointerMove : undefined}
                >
                    <planeGeometry args={[200, 200]} />
                    <meshBasicMaterial transparent opacity={0} depthWrite={false} />
                </mesh>

                <group ref={shapesRef}>
                    {shapesToRender.map(shape => (
                        <ShapeRenderer 
                            key={shape.id} 
                            shape={shape} 
