import React, { useRef, useState, useMemo, useEffect, useCallback } from 'react';
import { Canvas, useThree, ThreeEvent, useFrame } from '@react-three/fiber';
import { OrbitControls, Grid, Environment, TransformControls, Html, GizmoHelper, GizmoViewport } from '@react-three/drei';
import * as THREE from 'three';
import { OrbitControls as OrbitControlsImpl } from 'three-stdlib';
import { useApp } from '../context/AppContext';
import { ToolType, IPoint, IShape, ShapeType } from '../types';
import { SNAP_GRID, DEFAULT_COLOR, FLAT_COLOR, HIGHLIGHT_COLOR, DIMENSION_COLOR, DEFAULT_HEIGHT } from '../constants';
import { Eye, Box, Monitor, Smartphone, Video, Move3d } from 'lucide-react';

// --- Constants ---
const SNAP_THRESHOLD = 0.3; // Meters (Adsorption radius)
const ALIGN_THRESHOLD = 0.25; // Meters (Object alignment radius)
const EPSILON = 1e-5; // Floating point tolerance

// --- Types ---
type SnapType = 'none' | 'grid' | 'vertex' | 'midpoint' | 'edge' | 'face' | 'align';

interface SnapResult {
    position: THREE.Vector3;
    type: SnapType;
    distance: number;
    snapObjectId?: string; // ID of the object we snapped to
    snapEdge?: [THREE.Vector3, THREE.Vector3]; // The start/end of the edge we snapped to (for highlighting)
    guides?: THREE.Vector3[][];
}

type PushPullMode = 'top' | 'side' | 'none';

interface PushPullState {
    mode: PushPullMode;
    hoveredShapeId: string | null;
    hoveredEdgeIndex: number;
    dragStartPoint: THREE.Vector3 | null;
    originalHeight: number;
    originalPoints: IPoint[];
    normal: THREE.Vector3;
    dragHeight?: number; // Current dynamic height during drag
}

interface ShapeRendererProps {
    shape: IShape;
    isSelected: boolean;
    onSelect: (e: ThreeEvent<MouseEvent>) => void;
    pushPullState: PushPullState;
    pushPullHandlers: {
        handlePointerDown: (e: ThreeEvent<PointerEvent>) => void;
        handlePointerUp: () => void;
        handlePointerMove: (e: ThreeEvent<PointerEvent>) => void;
    };
    drawingHandlers: {
        handlePointerDown: (e: ThreeEvent<PointerEvent>) => void;
        handlePointerUp: (e: ThreeEvent<PointerEvent>) => void;
        handleClick: (e: ThreeEvent<MouseEvent>) => void;
    };
}

// --- Geometry Helpers ---
const createThreeShape = (points: IPoint[]) => {
  const shape = new THREE.Shape();
  if (!points || points.length === 0) return shape;
  if (points[0]) {
    // We negate Z because in Three.js Shape (2D), Y is up, but we rotate the mesh -90deg X.
    // So Shape Y maps to World Z. To keep orientation correct, we invert.
    shape.moveTo(points[0].x, -points[0].z); 
    for (let i = 1; i < points.length; i++) {
        if (points[i]) shape.lineTo(points[i].x, -points[i].z);
    }
  }
  shape.closePath();
  return shape;
};

const createCirclePoints = (radius: number, segments = 32): IPoint[] => {
  const points: IPoint[] = [];
  for (let i = 0; i < segments; i++) {
    const theta = (i / segments) * Math.PI * 2;
    points.push({ x: Math.cos(theta) * radius, y: 0, z: Math.sin(theta) * radius });
  }
  points.push(points[0]);
  return points;
};

const createArcPoints = (radius: number, segments = 16): IPoint[] => {
  const points: IPoint[] = [];
  points.push({ x: 0, y: 0, z: 0 });
  for (let i = 0; i <= segments; i++) {
    const theta = (i / segments) * (Math.PI / 2); 
    points.push({ x: Math.cos(theta) * radius, y: 0, z: Math.sin(theta) * radius });
  }
  points.push({ x: 0, y: 0, z: 0 });
  return points;
};

const transformPoint = (localP: IPoint, shape: IShape): THREE.Vector3 => {
    const sX = shape.scale[0];
    const sZ = shape.scale[2];
    const rot = shape.rotation;
    const cos = Math.cos(rot);
    const sin = Math.sin(rot);
    const xScaled = localP.x * sX;
    const zScaled = localP.z * sZ;
    const xRot = xScaled * cos - zScaled * sin;
    const zRot = xScaled * sin + zScaled * cos;
    return new THREE.Vector3(xRot + shape.position[0], shape.position[1], zRot + shape.position[2]);
};

const closestPointOnSegment = (p: THREE.Vector3, v: THREE.Vector3, w: THREE.Vector3): THREE.Vector3 => {
  const vwx = w.x - v.x;
  const vwy = w.y - v.y;
  const vwz = w.z - v.z;
  const vpx = p.x - v.x;
  const vpy = p.y - v.y;
  const vpz = p.z - v.z;
  const dot = vpx * vwx + vpy * vwy + vpz * vwz;
  const l2 = vwx * vwx + vwy * vwy + vwz * vwz;
  if (l2 === 0) return v;
  let t = dot / l2;
  t = Math.max(0, Math.min(1, t));
  return new THREE.Vector3(v.x + t * vwx, v.y + t * vwy, v.z + t * vwz);
};

// --- Hooks ---

const usePushPullManager = () => {
    const { shapes, updateShape, tool } = useApp();
    const [ppState, setPPState] = useState<PushPullState>({
        mode: 'none', hoveredShapeId: null, hoveredEdgeIndex: -1, dragStartPoint: null, originalHeight: 0, originalPoints: [], normal: new THREE.Vector3(0, 1, 0)
    });
    const [tempShape, setTempShape] = useState<IShape | null>(null);

    const handlePointerMove = useCallback((e: ThreeEvent<PointerEvent>) => {
        if (tool !== ToolType.PUSH_PULL) return;

        if (ppState.dragStartPoint && ppState.hoveredShapeId) {
             const shape = shapes.find(s => s.id === ppState.hoveredShapeId);
             if (!shape) return;

             const raycaster = new THREE.Raycaster();
             raycaster.setFromCamera(new THREE.Vector2(e.pointer.x, e.pointer.y), e.camera);

             const plane = new THREE.Plane();
             plane.setFromNormalAndCoplanarPoint(e.camera.getWorldDirection(new THREE.Vector3()).negate(), ppState.dragStartPoint);

             const intersection = new THREE.Vector3();
             raycaster.ray.intersectPlane(plane, intersection);

             if (intersection) {
                 const deltaY = intersection.y - ppState.dragStartPoint.y;
                 const newHeight = Math.max(0.01, ppState.originalHeight + deltaY);

                 // If pulling from flat, change type to solid
                 const updates: any = { height: newHeight };
                 if (shape.type === 'flat' && newHeight > 0.02) {
                     updates.type = 'solid';
                     updates.color = DEFAULT_COLOR; // Switch from yellow to default when made solid
                 }

                 setPPState(prev => ({ ...prev, dragHeight: newHeight }));
                 setTempShape({ ...shape, ...updates });
             }
        } else {
            e.stopPropagation();
            const obj = e.object;
            const shapeId = obj.userData?.id;
            if (shapeId) {
                const shape = shapes.find(s => s.id === shapeId);
                if (shape) {
                     const localY = (e.point.y - shape.position[1]);
                     const isTop = Math.abs(localY - shape.height * shape.scale[1]) < 0.1 || shape.type === 'flat';
                     setPPState(prev => ({ 
                         ...prev, 
                         mode: isTop ? 'top' : 'side', 
                         hoveredShapeId: shapeId,
                         hoveredEdgeIndex: -1 
                     }));
                }
            } else {
                 setPPState(prev => ({ ...prev, hoveredShapeId: null, mode: 'none' }));
            }
        }
    }, [tool, ppState, shapes]);

    const handlePointerDown = useCallback((e: ThreeEvent<PointerEvent>) => {
        if (tool !== ToolType.PUSH_PULL || !ppState.hoveredShapeId) return;
        e.stopPropagation();
        const shape = shapes.find(s => s.id === ppState.hoveredShapeId);
        if (!shape) return;

        setPPState(prev => ({
            ...prev,
            dragStartPoint: e.point.clone(),
            originalHeight: shape.height,
            originalPoints: shape.points,
            dragHeight: shape.height
        }));
        setTempShape(shape);
    }, [tool, ppState.hoveredShapeId, shapes]);

    const handlePointerUp = useCallback(() => {
        if (ppState.dragStartPoint && ppState.hoveredShapeId && tempShape) {
            updateShape(ppState.hoveredShapeId, { 
                height: tempShape.height, 
                type: tempShape.type,
                color: tempShape.color 
            });
        }
        setPPState(prev => ({ ...prev, dragStartPoint: null, dragHeight: undefined }));
        setTempShape(null);
    }, [ppState, tempShape, updateShape]);

    return {
        ppState,
        handlePointerMove,
        handlePointerDown,
        handlePointerUp,
        isDragging: !!ppState.dragStartPoint,
        tempShape
    };
};

const useDrawingManager = () => {
    const { tool, addShape, wallThickness, setTool } = useApp();
    const [drawPoints, setDrawPoints] = useState<IPoint[]>([]);
    const [cursorPos, setCursorPos] = useState(new THREE.Vector3());
    const [snapInfo, setSnapInfo] = useState<SnapResult | null>(null);
    const [isDragging, setIsDragging] = useState(false);
    const [drawingHeight, setDrawingHeight] = useState(0);

    const reset = () => {
        setDrawPoints([]);
        setIsDragging(false);
    };

    // Clean reset when tool changes
    useEffect(() => {
        reset();
    }, [tool]);

    const handleClick = useCallback((e: ThreeEvent<MouseEvent>) => {
        if (tool === ToolType.SELECT || tool === ToolType.PUSH_PULL) return;

        // --- Continuous Line / Poly Drawing Logic ---
        if (tool === ToolType.DRAW_LINE || tool === ToolType.DRAW_POLY) {
             const newPt = { x: cursorPos.x, y: 0, z: cursorPos.z };

             // --- Polygon Close Loop Logic ---
             if (tool === ToolType.DRAW_POLY && drawPoints.length > 2) {
                 const first = drawPoints[0];
                 const dist = Math.sqrt((newPt.x - first.x)**2 + (newPt.z - first.z)**2);
                 if (dist < SNAP_THRESHOLD) {
                     // Create a FLAT 2D Shape
                     const shape: IShape = {
                         id: `shape-${Date.now()}`,
                         type: 'flat', // CHANGED: Start as flat
                         points: drawPoints,
                         height: DEFAULT_HEIGHT, // CHANGED: Start with minimal height
                         color: FLAT_COLOR, // CHANGED: Start yellow/flat color
                         position: [0,0,0],
                         rotation: 0,
                         scale: [1,1,1],
                         name: 'Plane'
                     };
                     addShape(shape);
                     setTool(ToolType.SELECT); // Finish Poly
                     return;
                 }
             }

             // --- Line Drawing Logic ---
             if (tool === ToolType.DRAW_LINE) {
                if (drawPoints.length === 0) {
                    // First Click: Start point
                    setDrawPoints([newPt]);
                } else {
                    // Second Click: End point -> Create Wall
                    const start = drawPoints[0];
                    const end = newPt;

                    if (Math.abs(start.x - end.x) > 0.01 || Math.abs(start.z - end.z) > 0.01) {
                        const dist = Math.sqrt((end.x - start.x)**2 + (end.z - start.z)**2);
                        const angle = Math.atan2(end.z - start.z, end.x - start.x);
                        const thickness = wallThickness || 0.1;
                        const cx = (start.x + end.x) / 2;
                        const cz = (start.z + end.z) / 2;
                        const halfL = dist / 2;
                        const halfW = thickness / 2;
                        // Define wall centered at origin, then rotated/translated
                        const points = [
                            { x: -halfL, y: 0, z: -halfW }, 
                            { x: halfL, y: 0, z: -halfW }, 
                            { x: halfL, y: 0, z: halfW }, 
                            { x: -halfL, y: 0, z: halfW }
                        ];

                        addShape({
                            id: `wall-${Date.now()}`,
                            type: 'flat', // CHANGED: Wall now starts as Flat
                            name: 'Wall Base',
                            points,
                            height: DEFAULT_HEIGHT, // CHANGED: 0.01 height
                            color: FLAT_COLOR, // CHANGED: Yellow/Flat color
                            position: [cx, 0, cz],
                            rotation: -angle,
                            scale: [1, 1, 1]
                        });

                        // CONTINUOUS DRAWING: Set the new start point to the current end point
                        setDrawPoints([end]);
                    }
                }
             } else {
                 // Poly: Just accumulate points
                 setDrawPoints([...drawPoints, newPt]);
             }
        }
    }, [tool, cursorPos, drawPoints, addShape, setTool, wallThickness]);

    const handlePointerDown = useCallback((e: ThreeEvent<PointerEvent>) => {
        if (tool === ToolType.SELECT || tool === ToolType.PUSH_PULL) return;

        // For dragging tools (Rect, Circle, Measure), start drag on pointer down
        if (tool === ToolType.DRAW_RECT || tool === ToolType.DRAW_CIRCLE || tool === ToolType.DRAW_ARC || tool === ToolType.MEASURE) {
             setIsDragging(true);
             const startPt = { x: cursorPos.x, y: 0, z: cursorPos.z };
             setDrawPoints([startPt]);
        }
    }, [tool, cursorPos]);

    const handlePointerUp = useCallback((e: ThreeEvent<PointerEvent>) => {
        if (!isDragging) return;
        setIsDragging(false);

        // Only handle drag-to-create tools here
        if (tool === ToolType.DRAW_LINE || tool === ToolType.DRAW_POLY) return;

        if (drawPoints.length === 0) return;
        const start = drawPoints[0];
        const end = { x: cursorPos.x, y: 0, z: cursorPos.z };

        if (Math.abs(start.x - end.x) < 0.01 && Math.abs(start.z - end.z) < 0.01) {
            reset();
            return;
        }

        let newShape: IShape | null = null;
        const id = `shape-${Date.now()}`;

        if (tool === ToolType.DRAW_RECT) {
             const minX = Math.min(start.x, end.x);
             const maxX = Math.max(start.x, end.x);
             const minZ = Math.min(start.z, end.z);
             const maxZ = Math.max(start.z, end.z);
             const width = maxX - minX;
             const depth = maxZ - minZ;
             const center = { x: minX + width/2, y: 0, z: minZ + depth/2 };

             const localPoints = [
                 { x: -width/2, y: 0, z: -depth/2 },
                 { x: width/2, y: 0, z: -depth/2 },
                 { x: width/2, y: 0, z: depth/2 },
                 { x: -width/2, y: 0, z: depth/2 },
                 { x: -width/2, y: 0, z: -depth/2 }
             ];

             newShape = {
                 id, 
                 type: 'flat', // CHANGED: Flat by default
                 points: localPoints, 
                 height: DEFAULT_HEIGHT, 
                 color: FLAT_COLOR,
                 position: [center.x, 0, center.z], 
                 rotation: 0, 
                 scale: [1,1,1], 
                 name: 'Rectangle'
             };
        } else if (tool === ToolType.DRAW_CIRCLE) {
             const radius = start.distanceTo(activeEnd);
             infoText = `R: ${formatValue(radius)}`;
             const circlePts = [];
             for(let i=0; i<=32; i++) {
                 const t = (i/32) * Math.PI * 2;
                 circlePts.push(new THREE.Vector3(start.x + Math.cos(t)*radius, start.y, start.z + Math.sin(t)*radius));
             }
             previewShape = <SimpleLine points={circlePts} color="black" lineWidth={2} />;
        } else if (tool === ToolType.DRAW_ARC) {
             const radius = start.distanceTo(activeEnd);
             infoText = `R: ${formatValue(radius)}`;
             previewShape = <SimpleLine points={[start, activeEnd]} color="black" lineWidth={2} dashed />;
        }
    } else {
        if (snapInfo) {
             if (snapInfo.type !== 'grid') infoText = snapInfo.type;
             else infoText = `${formatValue(cursorPos.x)}, ${formatValue(cursorPos.z)}`;
        }
    }

    return (
        <group>
            {points.map((p, i) => (
                <mesh key={i} position={p}>
                    <sphereGeometry args={[0.05]} />
                    <meshBasicMaterial color="red" depthTest={false} />
                </mesh>
            ))}
            {previewShape}
            {snapInfo && <SnapIndicator position={snapInfo.position} type={snapInfo.type} snapEdge={snapInfo.snapEdge} />}
            {(infoText || (snapInfo && snapInfo.type !== 'grid')) && (
                 <CursorTooltip text={infoText || snapInfo!.type} position={cursorPos} type={snapInfo?.type} />
            )}
        </group>
    );
};

// ... existing geometry snap ...
const getGeometrySnap = (
    cursorPos: THREE.Vector3, 
    shapes: IShape[], 
    activePoints: IPoint[] = [],
    threshold: number,
    intersectedObject?: THREE.Intersection
): SnapResult => {
    let bestSnap: SnapResult = {
        position: new THREE.Vector3(
            Math.round(cursorPos.x / SNAP_GRID) * SNAP_GRID,
            cursorPos.y, 
            Math.round(cursorPos.z / SNAP_GRID) * SNAP_GRID
        ),
        type: 'grid',
        distance: Infinity
    };

    if (activePoints && activePoints.length > 0) {
        const first = activePoints[0];
        const pt = new THREE.Vector3(first.x, first.y, first.z);
        const dist = pt.distanceTo(cursorPos);
        if (dist < threshold) {
            return { position: pt, type: 'vertex', distance: dist };
        }
    }

    for (const shape of shapes) {
        if (shape.type === 'dimension') continue;
        const currentH = shape.height * shape.scale[1];
        const hasHeight = Math.abs(currentH) > 0.02; // Treat very flat objects as having no top snap for cleaner drawing

        for (let i = 0; i < shape.points.length; i++) {
            const worldPt = transformPoint(shape.points[i], shape);
            let dist = worldPt.distanceTo(cursorPos);
            if (dist < threshold && dist < bestSnap.distance) {
                bestSnap = { position: worldPt, type: 'vertex', distance: dist, snapObjectId: shape.id };
            }
            if (hasHeight) {
                const worldPtTop = worldPt.clone().setY(worldPt.y + currentH);
                dist = worldPtTop.distanceTo(cursorPos);
                if (dist < threshold && dist < bestSnap.distance) {
                    bestSnap = { position: worldPtTop, type: 'vertex', distance: dist, snapObjectId: shape.id };
                }
            }
        }
    }
    if (bestSnap.type === 'vertex') return bestSnap;

    let bestEdgeSnap: SnapResult | null = null;
    let minEdgeDist = threshold;
    for (const shape of shapes) {
        if (shape.type === 'dimension') continue;
        const pts = shape.points;
        const len = pts.length;
        const currentH = shape.height * shape.scale[1];
        const hasHeight = Math.abs(currentH) > 0.02;
        for (let i = 0; i < len; i++) {
             const p1 = transformPoint(pts[i], shape);
             const p2 = transformPoint(pts[(i + 1) % len], shape);
             const checkSegment = (v1: THREE.Vector3, v2: THREE.Vector3) => {
                 const mid = new THREE.Vector3().addVectors(v1, v2).multiplyScalar(0.5);
                 const distMid = mid.distanceTo(cursorPos);
                 if (distMid < threshold && distMid < minEdgeDist) {
                     bestEdgeSnap = { position: mid, type: 'midpoint', distance: distMid, snapObjectId: shape.id, snapEdge: [v1, v2] };
                     minEdgeDist = distMid;
                     return;
                 }
                 const projected = closestPointOnSegment(cursorPos, v1, v2);
                 const distEdge = projected.distanceTo(cursorPos);
                 if (distEdge < threshold && distEdge < minEdgeDist) {
                     bestEdgeSnap = { position: projected, type: 'edge', distance: distEdge, snapObjectId: shape.id, snapEdge: [v1, v2] };
                     minEdgeDist = distEdge;
                 }
             };
             checkSegment(p1, p2);
             if (hasHeight) {
                 const p1Top = p1.clone().setY(p1.y + currentH);
                 const p2Top = p2.clone().setY(p2.y + currentH);
                 checkSegment(p1Top, p2Top);
                 checkSegment(p1, p1Top);
             }
        }
    }
    if (bestEdgeSnap) return bestEdgeSnap;

    const getShapeUserData = (obj: THREE.Object3D) => {
        if (obj.userData?.isShape) return obj.userData;
        if (obj.parent?.userData?.isShape) return obj.parent.userData;
        return null;
    };
    const shapeData = intersectedObject ? getShapeUserData(intersectedObject.object) : null;
    if (intersectedObject && shapeData) {
         bestSnap = { position: intersectedObject.point, type: 'face', distance: 0, snapObjectId: shapeData.id };
         return bestSnap;
    }

    return bestSnap;
};

// --- Components ---

const SimpleLine: React.FC<{ points: (THREE.Vector3 | [number, number, number])[], color: string, dashed?: boolean, opacity?: number, transparent?: boolean, lineWidth?: number, depthTest?: boolean }> = ({ points, color, dashed, opacity, transparent, lineWidth, depthTest = true }) => {
    const ref = useRef<THREE.Line>(null);
    const geometry = useMemo(() => {
        const pts = points.map(p => (p instanceof THREE.Vector3 ? p : new THREE.Vector3(...p)));
        return new THREE.BufferGeometry().setFromPoints(pts);
    }, [points]);

    useFrame(() => {
        if (dashed && ref.current) {
            ref.current.computeLineDistances();
        }
    });

    return (
        <line ref={ref} geometry={geometry}>
            {dashed ? (
                <lineDashedMaterial color={color} dashSize={0.2} gapSize={0.1} transparent={transparent} opacity={opacity} depthTest={depthTest} toneMapped={false} />
            ) : (
                <lineBasicMaterial color={color} transparent={transparent} opacity={opacity} depthTest={depthTest} toneMapped={false} />
            )}
        </line>
    );
};

const SnapIndicator: React.FC<{ position: THREE.Vector3; type: SnapType; snapEdge?: [THREE.Vector3, THREE.Vector3] }> = ({ position, type, snapEdge }) => {
    return (
        <group position={position}>
            <mesh>
                <sphereGeometry args={[type === 'vertex' ? 0.1 : 0.05]} />
                <meshBasicMaterial color={type === 'midpoint' ? 'cyan' : (type === 'vertex' ? 'magenta' : 'orange')} depthTest={false} />
            </mesh>
            {type === 'edge' && snapEdge && (
                <SimpleLine points={[snapEdge[0], snapEdge[1]]} color="orange" lineWidth={3} depthTest={false} />
            )}
            {type === 'midpoint' && snapEdge && (
                 <SimpleLine points={[snapEdge[0], snapEdge[1]]} color="cyan" lineWidth={3} depthTest={false} />
            )}
        </group>
    );
};

const CursorTooltip: React.FC<{ text: string; position: THREE.Vector3; type?: SnapType }> = ({ text, position, type }) => {
    return (
        <Html position={[position.x, position.y + 0.5, position.z]} center style={{ pointerEvents: 'none' }}>
            <div className="bg-slate-900/80 text-white text-xs px-2 py-1 rounded backdrop-blur-sm border border-slate-600 whitespace-nowrap flex items-center gap-1">
                {type && <span className={`w-2 h-2 rounded-full ${type === 'grid' ? 'bg-slate-500' : 'bg-green-500'}`} />}
                {text}
            </div>
        </Html>
    );
};

const ShapeOutline: React.FC<{ shape: IShape; color: string; opacity: number }> = ({ shape, color, opacity }) => {
    const geometry = useMemo(() => {
        if (shape.type === 'flat') {
            // FIX: Align outline with the top face of the flat shape (Z = shape.height)
            // This prevents the "separated" visual artifact due to parallax between Y=0 and Y=height
            const z = shape.height; 
            const points = shape.points.map(p => new THREE.Vector3(p.x, -p.z, z));
            points.push(new THREE.Vector3(shape.points[0].x, -shape.points[0].z, z)); // Close loop
            return new THREE.BufferGeometry().setFromPoints(points);
        } else {
            const shape2D = createThreeShape(shape.points);
            const geom = new THREE.ExtrudeGeometry(shape2D, { depth: shape.height, bevelEnabled: false });
            const edges = new THREE.EdgesGeometry(geom);
            geom.dispose(); // Dispose intermediate geometry to prevent memory leaks
            return edges;
        }
    }, [shape.points, shape.height, shape.type]);

    if (shape.type === 'flat') {
         return (
            <line geometry={geometry} rotation={[-Math.PI / 2, 0, 0]}>
                 {/* Enable depthTest (default true) so polygonOffset works correctly to layer the line on top of the mesh */}
                <lineBasicMaterial color={color} transparent opacity={opacity} />
            </line>
         );
    }

    return (
        <lineSegments geometry={geometry} rotation={[-Math.PI / 2, 0, 0]}>
            <lineBasicMaterial color={color} transparent opacity={opacity} />
        </lineSegments>
    );
};

// Optimized Shape Renderer
const ShapeRenderer = React.memo(({ shape, isSelected, onSelect, pushPullState, pushPullHandlers, drawingHandlers }: ShapeRendererProps) => {
    const { unit, tool } = useApp();
    const [hovered, setHovered] = useState(false);

    const isPushPullMode = tool === ToolType.PUSH_PULL;
    const highlightColor = isPushPullMode ? shape.color : (isSelected ? HIGHLIGHT_COLOR : shape.color);

    const isTarget = pushPullState.hoveredShapeId === shape.id;
    const isDraggingTop = isTarget && !!pushPullState.dragStartPoint && pushPullState.mode === 'top';

    // Optimization: If dragging Top, use scaleY instead of regenerating geometry
    let scaleY = 1;
    if (isDraggingTop && pushPullState.dragHeight !== undefined && shape.height > 0) {
        scaleY = pushPullState.dragHeight / shape.height;
    }

    const shape2D = useMemo(() => createThreeShape(shape.points), [shape.points]);

    if (shape.type === 'dimension') {
         // Dimension rendering logic (same as before)
         if (shape.points.length < 2) return null;
         const start = new THREE.Vector3(shape.points[0].x, shape.points[0].y, shape.points[0].z);
         const end = new THREE.Vector3(shape.points[1].x, shape.points[1].y, shape.points[1].z);
         const dist = start.distanceTo(end);
         const labelText = unit === 'cm' ? `${(dist * 100).toFixed(1)} cm` : `${dist.toFixed(3)} m`;
         return (
             <group onClick={onSelect} userData={{ isShape: true, id: shape.id }} name="dimension_group">
                <SimpleLine points={[[start.x, start.y+0.05, start.z], [end.x, end.y+0.05, end.z]]} color={isSelected ? HIGHLIGHT_COLOR : shape.color} lineWidth={2} depthTest={false} />
                <mesh position={[start.x, start.y + 0.05, start.z]}><sphereGeometry args={[0.05]} /><meshBasicMaterial color={shape.color} depthTest={false}/></mesh>
                <mesh position={[end.x, end.y + 0.05, end.z]}><sphereGeometry args={[0.05]} /><meshBasicMaterial color={shape.color} depthTest={false}/></mesh>
                <Html position={[(start.x+end.x)/2, (start.y+end.y)/2 + 0.5, (start.z+end.z)/2]} center>
                    <div className="bg-slate-900/90 text-yellow-400 font-mono text-xs px-2 py-1 rounded border border-yellow-500/50 backdrop-blur-sm pointer-events-none whitespace-nowrap shadow-lg">{labelText}</div>
                </Html>
             </group>
         );
    }

    return (
        <group 
            position={[shape.position[0], shape.position[1], shape.position[2]]} 
            rotation={[0, shape.rotation, 0]} 
            scale={[shape.scale[0], shape.scale[1] * scaleY, shape.scale[2]]} 
            userData={{ isShape: true, id: shape.id }} 
            name="shape_group" 
            onClick={!isPushPullMode ? onSelect : undefined}
            onPointerOver={(e) => { 
                e.stopPropagation(); 
                setHovered(true); 
            }}
            onPointerOut={() => { 
                setHovered(false); 
                document.body.style.cursor = 'default'; 
            }}
            onPointerDown={(e) => {
                if (isPushPullMode) pushPullHandlers.handlePointerDown(e);
                else drawingHandlers.handlePointerDown(e);
            }}
            onPointerMove={isPushPullMode ? pushPullHandlers.handlePointerMove : undefined}
            onPointerUp={(e) => {
                pushPullHandlers.handlePointerUp();
                drawingHandlers.handlePointerUp(e);
            }}
        >
            <mesh rotation={[-Math.PI/2, 0, 0]} castShadow receiveShadow userData={{ isShape: true, id: shape.id }}>
                <extrudeGeometry args={[shape2D, { depth: shape.height, bevelEnabled: false }]} />
                <meshStandardMaterial 
                    color={highlightColor} 
                    transparent={shape.type === 'flat'} 
                    opacity={shape.type === 'flat' ? 0.6 : 1.0} 
                    polygonOffset={shape.type === 'flat'} 
                    polygonOffsetFactor={shape.type === 'flat' ? 1 : 0} 
                    polygonOffsetUnits={1}
                    side={THREE.DoubleSide} // <--- Fix: Render both sides to prevent invisible faces
                    shadowSide={THREE.DoubleSide} // <--- Fix: Cast shadows from both sides
                />
            </mesh>
            <ShapeOutline shape={shape} color="#000000" opacity={isPushPullMode ? 0.2 : 0.8} />
        </group>
    );
});

import React, { useRef, useState, useMemo, useCallback } from 'react';
import { Canvas, useThree, ThreeEvent, useFrame } from '@react-three/fiber';
import { OrbitControls, Grid, Environment, Html } from '@react-three/drei';
import * as THREE from 'three';
import { useApp } from '../context/AppContext';
import { ToolType, IPoint, IShape, ShapeType } from '../types';
import { SNAP_GRID, DEFAULT_COLOR, FLAT_COLOR, HIGHLIGHT_COLOR, DEFAULT_HEIGHT } from '../constants';

// --- Constants ---
const SNAP_THRESHOLD = 0.3; // Meters (Adsorption radius)

// --- Types ---
type SnapType = 'none' | 'grid' | 'vertex' | 'midpoint' | 'edge' | 'face' | 'align';

interface SnapResult {
    position: THREE.Vector3;
    type: SnapType;
    distance: number;
    snapObjectId?: string; // ID of the object we snapped to
    snapEdge?: [THREE.Vector3, THREE.Vector3]; // The start/end of the edge we snapped to (for highlighting)
    guides?: THREE.Vector3[][];
}

type PushPullMode = 'top' | 'side' | 'none';

interface PushPullState {
    mode: PushPullMode;
    hoveredShapeId: string | null;
    hoveredEdgeIndex: number;
    dragStartPoint: THREE.Vector3 | null;
    originalHeight: number;
    originalPoints: IPoint[];
    normal: THREE.Vector3;
    dragHeight?: number; // Current dynamic height during drag
}

interface ShapeRendererProps {
    shape: IShape;
    isSelected: boolean;
    onSelect: (e: ThreeEvent<MouseEvent>) => void;
    pushPullState: PushPullState;
    pushPullHandlers: {
        handlePointerDown: (e: ThreeEvent<PointerEvent>) => void;
        handlePointerUp: () => void;
        handlePointerMove: (e: ThreeEvent<PointerEvent>) => void;
    };
    drawingHandlers: {
        handlePointerDown: (e: ThreeEvent<PointerEvent>) => void;
        handlePointerUp: (e: ThreeEvent<PointerEvent>) => void;
        handleClick: (e: ThreeEvent<MouseEvent>) => void;
        handlePointerMove: (e: ThreeEvent<PointerEvent>) => void;
    };
}

// --- Geometry Helpers ---
const createThreeShape = (points: IPoint[]) => {
  const shape = new THREE.Shape();
  if (!points || points.length === 0) return shape;
  if (points[0]) {
    shape.moveTo(points[0].x, -points[0].z); 
    for (let i = 1; i < points.length; i++) {
        if (points[i]) shape.lineTo(points[i].x, -points[i].z);
    }
  }
  shape.closePath();
  return shape;
};

const transformPoint = (localP: IPoint, shape: IShape): THREE.Vector3 => {
    const sX = shape.scale[0];
    const sZ = shape.scale[2];
    const rot = shape.rotation;
    const cos = Math.cos(rot);
    const sin = Math.sin(rot);
    const xScaled = localP.x * sX;
    const zScaled = localP.z * sZ;
    const xRot = xScaled * cos - zScaled * sin;
    const zRot = xScaled * sin + zScaled * cos;
    return new THREE.Vector3(xRot + shape.position[0], shape.position[1], zRot + shape.position[2]);
};

const closestPointOnSegment = (p: THREE.Vector3, v: THREE.Vector3, w: THREE.Vector3): THREE.Vector3 => {
  const vwx = w.x - v.x;
  const vwy = w.y - v.y;
  const vwz = w.z - v.z;
  const vpx = p.x - v.x;
  const vpy = p.y - v.y;
  const vpz = p.z - v.z;
  const dot = vpx * vwx + vpy * vwy + vpz * vwz;
  const l2 = vwx * vwx + vwy * vwy + vwz * vwz;
  if (l2 === 0) return v;
  let t = dot / l2;
  t = Math.max(0, Math.min(1, t));
  return new THREE.Vector3(v.x + t * vwx, v.y + t * vwy, v.z + t * vwz);
};

const getGeometrySnap = (
    cursorPos: THREE.Vector3, 
    shapes: IShape[], 
    activePoints: IPoint[] = [],
    threshold: number,
    intersectedObject?: THREE.Intersection
): SnapResult => {
    let bestSnap: SnapResult = {
        position: new THREE.Vector3(
            Math.round(cursorPos.x / SNAP_GRID) * SNAP_GRID,
            cursorPos.y, 
            Math.round(cursorPos.z / SNAP_GRID) * SNAP_GRID
        ),
        type: 'grid',
        distance: Infinity
    };

    if (activePoints && activePoints.length > 0) {
        const first = activePoints[0];
        const pt = new THREE.Vector3(first.x, first.y, first.z);
        const dist = pt.distanceTo(cursorPos);
        if (dist < threshold) {
            return { position: pt, type: 'vertex', distance: dist };
        }
    }

    for (const shape of shapes) {
        if (shape.type === 'dimension') continue;
        const currentH = shape.height * shape.scale[1];
        const hasHeight = Math.abs(currentH) > 0.02;

        for (let i = 0; i < shape.points.length; i++) {
            const worldPt = transformPoint(shape.points[i], shape);
            let dist = worldPt.distanceTo(cursorPos);
            if (dist < threshold && dist < bestSnap.distance) {
                bestSnap = { position: worldPt, type: 'vertex', distance: dist, snapObjectId: shape.id };
            }
            if (hasHeight) {
                const worldPtTop = worldPt.clone().setY(worldPt.y + currentH);
                dist = worldPtTop.distanceTo(cursorPos);
                if (dist < threshold && dist < bestSnap.distance) {
                    bestSnap = { position: worldPtTop, type: 'vertex', distance: dist, snapObjectId: shape.id };
                }
            }
        }
    }
    if (bestSnap.type === 'vertex') return bestSnap;

    let bestEdgeSnap: SnapResult | null = null;
    let minEdgeDist = threshold;
    for (const shape of shapes) {
        if (shape.type === 'dimension') continue;
        const pts = shape.points;
        const len = pts.length;
        const currentH = shape.height * shape.scale[1];
        const hasHeight = Math.abs(currentH) > 0.02;
        for (let i = 0; i < len; i++) {
             const p1 = transformPoint(pts[i], shape);
             const p2 = transformPoint(pts[(i + 1) % len], shape);
             const checkSegment = (v1: THREE.Vector3, v2: THREE.Vector3) => {
                 const mid = new THREE.Vector3().addVectors(v1, v2).multiplyScalar(0.5);
                 const distMid = mid.distanceTo(cursorPos);
                 if (distMid < threshold && distMid < minEdgeDist) {
                     bestEdgeSnap = { position: mid, type: 'midpoint', distance: distMid, snapObjectId: shape.id, snapEdge: [v1, v2] };
                     minEdgeDist = distMid;
                     return;
                 }
                 const projected = closestPointOnSegment(cursorPos, v1, v2);
                 const distEdge = projected.distanceTo(cursorPos);
                 if (distEdge < threshold && distEdge < minEdgeDist) {
                     bestEdgeSnap = { position: projected, type: 'edge', distance: distEdge, snapObjectId: shape.id, snapEdge: [v1, v2] };
                     minEdgeDist = distEdge;
                 }
             };
             checkSegment(p1, p2);
             if (hasHeight) {
                 const p1Top = p1.clone().setY(p1.y + currentH);
                 const p2Top = p2.clone().setY(p2.y + currentH);
                 checkSegment(p1Top, p2Top);
                 checkSegment(p1, p1Top);
             }
        }
    }
    if (bestEdgeSnap) return bestEdgeSnap;

    const getShapeUserData = (obj: THREE.Object3D) => {
        if (obj.userData?.isShape) return obj.userData;
        if (obj.parent?.userData?.isShape) return obj.parent.userData;
        return null;
    };
    const shapeData = intersectedObject ? getShapeUserData(intersectedObject.object) : null;
    if (intersectedObject && shapeData) {
         bestSnap = { position: intersectedObject.point, type: 'face', distance: 0, snapObjectId: shapeData.id };
         return bestSnap;
    }

    return bestSnap;
};

// --- Helper Components ---

const SimpleLine: React.FC<{ points: (THREE.Vector3 | [number, number, number])[], color: string, dashed?: boolean, opacity?: number, transparent?: boolean, lineWidth?: number, depthTest?: boolean }> = ({ points, color, dashed, opacity, transparent, lineWidth, depthTest = true }) => {
    const ref = useRef<THREE.Line>(null);
    const geometry = useMemo(() => {
        const pts = points.map(p => (p instanceof THREE.Vector3 ? p : new THREE.Vector3(...p)));
        return new THREE.BufferGeometry().setFromPoints(pts);
    }, [points]);

    useFrame(() => {
        if (dashed && ref.current) {
            ref.current.computeLineDistances();
        }
    });

    return (
        <line ref={ref} geometry={geometry}>
            {dashed ? (
                <lineDashedMaterial color={color} dashSize={0.2} gapSize={0.1} transparent={transparent} opacity={opacity} depthTest={depthTest} toneMapped={false} />
            ) : (
                <lineBasicMaterial color={color} transparent={transparent} opacity={opacity} depthTest={depthTest} toneMapped={false} />
            )}
        </line>
    );
};

const SnapIndicator: React.FC<{ position: THREE.Vector3; type: SnapType; snapEdge?: [THREE.Vector3, THREE.Vector3] }> = ({ position, type, snapEdge }) => {
    return (
        <group position={position}>
            <mesh>
                <sphereGeometry args={[type === 'vertex' ? 0.1 : 0.05]} />
                <meshBasicMaterial color={type === 'midpoint' ? 'cyan' : (type === 'vertex' ? 'magenta' : 'orange')} depthTest={false} />
            </mesh>
            {type === 'edge' && snapEdge && (
                <SimpleLine points={[snapEdge[0], snapEdge[1]]} color="orange" lineWidth={3} depthTest={false} />
            )}
            {type === 'midpoint' && snapEdge && (
                 <SimpleLine points={[snapEdge[0], snapEdge[1]]} color="cyan" lineWidth={3} depthTest={false} />
            )}
        </group>
    );
};

const CursorTooltip: React.FC<{ text: string; position: THREE.Vector3; type?: SnapType }> = ({ text, position, type }) => {
    return (
        <Html position={[position.x, position.y + 0.5, position.z]} center style={{ pointerEvents: 'none' }}>
            <div className="bg-slate-900/80 text-white text-xs px-2 py-1 rounded backdrop-blur-sm border border-slate-600 whitespace-nowrap flex items-center gap-1">
                {type && <span className={`w-2 h-2 rounded-full ${type === 'grid' ? 'bg-slate-500' : 'bg-green-500'}`} />}
                {text}
            </div>
        </Html>
    );
};

const ShapeOutline: React.FC<{ shape: IShape; color: string; opacity: number }> = ({ shape, color, opacity }) => {
    const geometry = useMemo(() => {
        if (shape.type === 'flat') {
            const z = shape.height; 
            const points = shape.points.map(p => new THREE.Vector3(p.x, -p.z, z));
            points.push(new THREE.Vector3(shape.points[0].x, -shape.points[0].z, z)); // Close loop
            return new THREE.BufferGeometry().setFromPoints(points);
        } else {
            const shape2D = createThreeShape(shape.points);
            const geom = new THREE.ExtrudeGeometry(shape2D, { depth: shape.height, bevelEnabled: false });
            const edges = new THREE.EdgesGeometry(geom);
            geom.dispose(); 
            return edges;
        }
    }, [shape.points, shape.height, shape.type]);

    if (shape.type === 'flat') {
         return (
            <line geometry={geometry} rotation={[-Math.PI / 2, 0, 0]}>
                <lineBasicMaterial color={color} transparent opacity={opacity} />
            </line>
         );
    }

    return (
        <lineSegments geometry={geometry} rotation={[-Math.PI / 2, 0, 0]}>
            <lineBasicMaterial color={color} transparent opacity={opacity} />
        </lineSegments>
    );
};

// Optimized Shape Renderer
const ShapeRenderer = React.memo(({ shape, isSelected, onSelect, pushPullState, pushPullHandlers, drawingHandlers }: ShapeRendererProps) => {
    const { unit, tool } = useApp();
    const [hovered, setHovered] = useState(false);

    const isPushPullMode = tool === ToolType.PUSH_PULL;
    const highlightColor = isPushPullMode ? shape.color : (isSelected ? HIGHLIGHT_COLOR : shape.color);

    const isTarget = pushPullState.hoveredShapeId === shape.id;
    const isDraggingTop = isTarget && !!pushPullState.dragStartPoint && pushPullState.mode === 'top';

    let scaleY = 1;
    if (isDraggingTop && pushPullState.dragHeight !== undefined && shape.height > 0) {
        scaleY = pushPullState.dragHeight / shape.height;
    }

    const shape2D = useMemo(() => createThreeShape(shape.points), [shape.points]);

    if (shape.type === 'dimension') {
         if (shape.points.length < 2) return null;
         const start = new THREE.Vector3(shape.points[0].x, shape.points[0].y, shape.points[0].z);
         const end = new THREE.Vector3(shape.points[1].x, shape.points[1].y, shape.points[1].z);
         const dist = start.distanceTo(end);
         const labelText = unit === 'cm' ? `${(dist * 100).toFixed(1)} cm` : `${dist.toFixed(3)} m`;
         return (
             <group onClick={onSelect} userData={{ isShape: true, id: shape.id }} name="dimension_group">
                <SimpleLine points={[[start.x, start.y+0.05, start.z], [end.x, end.y+0.05, end.z]]} color={isSelected ? HIGHLIGHT_COLOR : shape.color} lineWidth={2} depthTest={false} />
                <mesh position={[start.x, start.y + 0.05, start.z]}><sphereGeometry args={[0.05]} /><meshBasicMaterial color={shape.color} depthTest={false}/></mesh>
                <mesh position={[end.x, end.y + 0.05, end.z]}><sphereGeometry args={[0.05]} /><meshBasicMaterial color={shape.color} depthTest={false}/></mesh>
                <Html position={[(start.x+end.x)/2, (start.y+end.y)/2 + 0.5, (start.z+end.z)/2]} center>
                    <div className="bg-slate-900/90 text-yellow-400 font-mono text-xs px-2 py-1 rounded border border-yellow-500/50 backdrop-blur-sm pointer-events-none whitespace-nowrap shadow-lg">{labelText}</div>
                </Html>
             </group>
         );
    }

    return (
        <group 
            position={[shape.position[0], shape.position[1], shape.position[2]]} 
            rotation={[0, shape.rotation, 0]} 
            scale={[shape.scale[0], shape.scale[1] * scaleY, shape.scale[2]]} 
            userData={{ isShape: true, id: shape.id }} 
            name="shape_group" 
            onClick={!isPushPullMode ? onSelect : undefined}
            onPointerOver={(e) => { 
                e.stopPropagation(); 
                setHovered(true); 
            }}
            onPointerOut={() => { 
                setHovered(false); 
                document.body.style.cursor = 'default'; 
            }}
            onPointerDown={(e) => {
                if (isPushPullMode) pushPullHandlers.handlePointerDown(e);
                else drawingHandlers.handlePointerDown(e);
            }}
            onPointerMove={isPushPullMode ? pushPullHandlers.handlePointerMove : undefined}
            onPointerUp={(e) => {
                pushPullHandlers.handlePointerUp();
                drawingHandlers.handlePointerUp(e);
            }}
        >
            <mesh rotation={[-Math.PI/2, 0, 0]} castShadow receiveShadow userData={{ isShape: true, id: shape.id }}>
                <extrudeGeometry args={[shape2D, { depth: shape.height, bevelEnabled: false }]} />
                <meshStandardMaterial 
                    color={highlightColor} 
                    transparent={shape.type === 'flat'} 
                    opacity={shape.type === 'flat' ? 0.6 : 1.0} 
                    polygonOffset={shape.type === 'flat'} 
                    polygonOffsetFactor={shape.type === 'flat' ? 1 : 0} 
                    polygonOffsetUnits={1}
                    side={THREE.DoubleSide} 
                    shadowSide={THREE.DoubleSide} 
                />
            </mesh>
            <ShapeOutline shape={shape} color="#000000" opacity={isPushPullMode ? 0.2 : 0.8} />
        </group>
    );
});

// --- Hooks ---

const usePushPullManager = () => {
    const { shapes, updateShape, tool } = useApp();
    const [ppState, setPPState] = useState<PushPullState>({
        mode: 'none', hoveredShapeId: null, hoveredEdgeIndex: -1, dragStartPoint: null, originalHeight: 0, originalPoints: [], normal: new THREE.Vector3(0, 1, 0)
    });
    const [tempShape, setTempShape] = useState<IShape | null>(null);

    const handlePointerMove = useCallback((e: ThreeEvent<PointerEvent>) => {
        if (tool !== ToolType.PUSH_PULL) return;

        if (ppState.dragStartPoint && ppState.hoveredShapeId) {
             const shape = shapes.find(s => s.id === ppState.hoveredShapeId);
             if (!shape) return;

             const raycaster = new THREE.Raycaster();
             raycaster.setFromCamera(new THREE.Vector2(e.pointer.x, e.pointer.y), e.camera);

             const plane = new THREE.Plane();
             plane.setFromNormalAndCoplanarPoint(e.camera.getWorldDirection(new THREE.Vector3()).negate(), ppState.dragStartPoint);

             const intersection = new THREE.Vector3();
             raycaster.ray.intersectPlane(plane, intersection);

             if (intersection) {
                 const deltaY = intersection.y - ppState.dragStartPoint.y;
                 const newHeight = Math.max(0.01, ppState.originalHeight + deltaY);

                 const updates: any = { height: newHeight };
                 if (shape.type === 'flat' && newHeight > 0.02) {
                     updates.type = 'solid';
                     updates.color = DEFAULT_COLOR; 
                 }

                 setPPState(prev => ({ ...prev, dragHeight: newHeight }));
                 setTempShape({ ...shape, ...updates });
             }
        } else {
            e.stopPropagation();
            const obj = e.object;
            const shapeId = obj.userData?.id;
            if (shapeId) {
                const shape = shapes.find(s => s.id === shapeId);
                if (shape) {
                     const localY = (e.point.y - shape.position[1]);
                     const isTop = Math.abs(localY - shape.height * shape.scale[1]) < 0.1 || shape.type === 'flat';
                     setPPState(prev => ({ 
                         ...prev, 
                         mode: isTop ? 'top' : 'side', 
                         hoveredShapeId: shapeId,
                         hoveredEdgeIndex: -1 
                     }));
                }
            } else {
                 setPPState(prev => ({ ...prev, hoveredShapeId: null, mode: 'none' }));
            }
        }
    }, [tool, ppState, shapes]);

    const handlePointerDown = useCallback((e: ThreeEvent<PointerEvent>) => {
        if (tool !== ToolType.PUSH_PULL || !ppState.hoveredShapeId) return;
        e.stopPropagation();
        const shape = shapes.find(s => s.id === ppState.hoveredShapeId);
        if (!shape) return;

        setPPState(prev => ({
            ...prev,
            dragStartPoint: e.point.clone(),
            originalHeight: shape.height,
            originalPoints: shape.points,
            dragHeight: shape.height
        }));
        setTempShape(shape);
    }, [tool, ppState.hoveredShapeId, shapes]);

    const handlePointerUp = useCallback(() => {
        if (ppState.dragStartPoint && ppState.hoveredShapeId && tempShape) {
            updateShape(ppState.hoveredShapeId, { 
                height: tempShape.height, 
                type: tempShape.type,
                color: tempShape.color 
            });
        }
        setPPState(prev => ({ ...prev, dragStartPoint: null, dragHeight: undefined }));
        setTempShape(null);
    }, [ppState, tempShape, updateShape]);

    return {
        ppState,
        handlePointerMove,
        handlePointerDown,
        handlePointerUp,
        isDragging: !!ppState.dragStartPoint,
        tempShape
    };
};

const useDrawingLogic = () => {
    const { tool, addShape, wallThickness, setTool, shapes, formatValue } = useApp();
    const [drawPoints, setDrawPoints] = useState<IPoint[]>([]);
    const [cursorPos, setCursorPos] = useState(new THREE.Vector3());
    const [snapInfo, setSnapInfo] = useState<SnapResult | null>(null);
    const [isDragging, setIsDragging] = useState(false);

    // Reset when tool changes
    const reset = useCallback(() => {
        setDrawPoints([]);
        setIsDragging(false);
    }, []);

    React.useEffect(() => {
        reset();
    }, [tool, reset]);

    const handlePointerMove = useCallback((e: ThreeEvent<PointerEvent>) => {
        if (tool === ToolType.SELECT || tool === ToolType.PUSH_PULL) return;
        const snap = getGeometrySnap(e.point, shapes, drawPoints, 0.2, e.intersections[0]);
        setSnapInfo(snap);
        setCursorPos(snap.position);
    }, [tool, shapes, drawPoints]);

    const handleClick = useCallback((e: ThreeEvent<MouseEvent>) => {
        if (tool === ToolType.SELECT || tool === ToolType.PUSH_PULL) return;

        // Use snapped position
        const p = snapInfo ? snapInfo.position : e.point;
        const newPt = { x: p.x, y: 0, z: p.z };

        if (tool === ToolType.DRAW_LINE || tool === ToolType.DRAW_POLY) {
             if (tool === ToolType.DRAW_POLY && drawPoints.length > 2) {
                 const first = drawPoints[0];
                 const dist = Math.sqrt((newPt.x - first.x)**2 + (newPt.z - first.z)**2);
                 if (dist < SNAP_THRESHOLD) {
                     addShape({
                         id: `shape-${Date.now()}`,
                         type: 'flat',
                         points: drawPoints,
                         height: DEFAULT_HEIGHT,
                         color: FLAT_COLOR,
                         position: [0,0,0],
                         rotation: 0,
                         scale: [1,1,1],
                         name: 'Plane'
                     });
                     setTool(ToolType.SELECT);
                     return;
                 }
             }

             if (tool === ToolType.DRAW_LINE) {
                if (drawPoints.length === 0) {
                    setDrawPoints([newPt]);
                } else {
                    const start = drawPoints[0];
                    const end = newPt;
                    if (Math.abs(start.x - end.x) > 0.01 || Math.abs(start.z - end.z) > 0.01) {
                        const dist = Math.sqrt((end.x - start.x)**2 + (end.z - start.z)**2);
                        const angle = Math.atan2(end.z - start.z, end.x - start.x);
                        const thickness = wallThickness || 0.1;
                        const cx = (start.x + end.x) / 2;
                        const cz = (start.z + end.z) / 2;
                        const halfL = dist / 2;
                        const halfW = thickness / 2;
                        const points = [
                            { x: -halfL, y: 0, z: -halfW }, 
                            { x: halfL, y: 0, z: -halfW }, 
                            { x: halfL, y: 0, z: halfW }, 
                            { x: -halfL, y: 0, z: halfW }
                        ];

                        addShape({
                            id: `wall-${Date.now()}`,
                            type: 'flat',
                            name: 'Wall Base',
                            points,
                            height: DEFAULT_HEIGHT,
                            color: FLAT_COLOR,
                            position: [cx, 0, cz],
                            rotation: -angle,
                            scale: [1, 1, 1]
                        });
                        setDrawPoints([end]);
                    }
                }
             } else {
                 setDrawPoints([...drawPoints, newPt]);
             }
        }
    }, [tool, drawPoints, addShape, setTool, wallThickness, snapInfo]);

    const handlePointerDown = useCallback((e: ThreeEvent<PointerEvent>) => {
        if (tool === ToolType.SELECT || tool === ToolType.PUSH_PULL) return;
        if (tool === ToolType.DRAW_RECT || tool === ToolType.DRAW_CIRCLE || tool === ToolType.DRAW_ARC || tool === ToolType.MEASURE) {
             setIsDragging(true);
             const p = snapInfo ? snapInfo.position : e.point;
             const startPt = { x: p.x, y: 0, z: p.z };
             setDrawPoints([startPt]);
        }
    }, [tool, snapInfo]);

    const handlePointerUp = useCallback((e: ThreeEvent<PointerEvent>) => {
        if (!isDragging) return;
        setIsDragging(false);

        if (tool === ToolType.DRAW_LINE || tool === ToolType.DRAW_POLY) return;

        if (drawPoints.length === 0) return;
        const start = drawPoints[0];
        const p = snapInfo ? snapInfo.position : e.point;
        const end = { x: p.x, y: 0, z: p.z };

        if (Math.abs(start.x - end.x) < 0.01 && Math.abs(start.z - end.z) < 0.01) {
            reset();
            return;
        }

        const id = `shape-${Date.now()}`;

        if (tool === ToolType.DRAW_RECT) {
             const minX = Math.min(start.x, end.x);
             const maxX = Math.max(start.x, end.x);
             const minZ = Math.min(start.z, end.z);
             const maxZ = Math.max(start.z, end.z);
             const width = maxX - minX;
             const depth = maxZ - minZ;
             const center = { x: minX + width/2, y: 0, z: minZ + depth/2 };

             const localPoints = [
                 { x: -width/2, y: 0, z: -depth/2 },
                 { x: width/2, y: 0, z: -depth/2 },
                 { x: width/2, y: 0, z: depth/2 },
                 { x: -width/2, y: 0, z: depth/2 },
                 { x: -width/2, y: 0, z: -depth/2 }
             ];

             addShape({
                 id, 
                 type: 'flat', 
                 points: localPoints, 
                 height: DEFAULT_HEIGHT, 
                 color: FLAT_COLOR,
                 position: [center.x, 0, center.z], 
                 rotation: 0, 
                 scale: [1,1,1], 
                 name: 'Rectangle'
             });
        } else if (tool === ToolType.DRAW_CIRCLE) {
            const startVec = new THREE.Vector3(start.x, 0, start.z);
            const endVec = new THREE.Vector3(end.x, 0, end.z);
            const radius = startVec.distanceTo(endVec);
            const circlePts: IPoint[] = [];
            for(let i=0; i<=32; i++) {
                const t = (i/32) * Math.PI * 2;
                circlePts.push({ x: Math.cos(t)*radius, y: 0, z: Math.sin(t)*radius });
            }
             addShape({
                 id, 
                 type: 'flat', 
                 points: circlePts, 
                 height: DEFAULT_HEIGHT, 
                 color: FLAT_COLOR,
                 position: [start.x, 0, start.z], 
                 rotation: 0, 
                 scale: [1,1,1], 
                 name: 'Circle'
             });
        } else if (tool === ToolType.MEASURE) {
             addShape({
                 id, 
                 type: 'dimension', 
                 points: [start, end], 
                 height: 0, 
                 color: DIMENSION_COLOR,
                 position: [0, 0, 0], 
                 rotation: 0, 
                 scale: [1,1,1], 
                 name: 'Dimension'
             });
        }

        if (tool !== ToolType.MEASURE) {
            setTool(ToolType.SELECT);
        }
        reset();
    }, [isDragging, tool, drawPoints, snapInfo, addShape, setTool, reset]);

    // Calculate Preview Elements
    const activeEnd = snapInfo?.position || cursorPos;
    let infoText = '';
    let previewShape: React.ReactNode = null;

    if (drawPoints.length > 0) {
        const start = drawPoints[0];

        if (tool === ToolType.DRAW_RECT && isDragging) {
             const width = Math.abs(activeEnd.x - start.x);
             const depth = Math.abs(activeEnd.z - start.z);
             infoText = `${formatValue(width)} x ${formatValue(depth)}`;

             const minX = Math.min(start.x, activeEnd.x);
             const maxX = Math.max(start.x, activeEnd.x);
             const minZ = Math.min(start.z, activeEnd.z);
             const maxZ = Math.max(start.z, activeEnd.z);

             const pts = [
                 new THREE.Vector3(minX, 0.05, minZ),
                 new THREE.Vector3(maxX, 0.05, minZ),
                 new THREE.Vector3(maxX, 0.05, maxZ),
                 new THREE.Vector3(minX, 0.05, maxZ),
                 new THREE.Vector3(minX, 0.05, minZ)
             ];
             previewShape = <SimpleLine points={pts} color="white" lineWidth={2} dashed />;
        } else if (tool === ToolType.DRAW_CIRCLE && isDragging) {
             const startVec = new THREE.Vector3(start.x, 0, start.z);
             const dist = startVec.distanceTo(activeEnd);
             infoText = `R: ${formatValue(dist)}`;

             const pts = [];
             for(let i=0; i<=32; i++) {
                 const t = (i/32) * Math.PI * 2;
                 pts.push(new THREE.Vector3(start.x + Math.cos(t)*dist, 0.05, start.z + Math.sin(t)*dist));
             }
             previewShape = <SimpleLine points={pts} color="white" lineWidth={2} dashed />;
        } else if (tool === ToolType.DRAW_LINE || tool === ToolType.DRAW_POLY) {
             const pts = drawPoints.map(p => new THREE.Vector3(p.x, 0.05, p.z));
             pts.push(new THREE.Vector3(activeEnd.x, 0.05, activeEnd.z));
             if (tool === ToolType.DRAW_POLY && drawPoints.length > 0) {
                 const dist = activeEnd.distanceTo(new THREE.Vector3(drawPoints[0].x, activeEnd.y, drawPoints[0].z));
                 if (dist < SNAP_THRESHOLD) {
                     infoText = "Close Loop";
                 }
             }
             // For line drawing (wall), show thickness preview? Simplified to single line for now
             previewShape = <SimpleLine points={pts} color="white" lineWidth={2} />;
        } else if (tool === ToolType.MEASURE && isDragging) {
             const startVec = new THREE.Vector3(start.x, 0, start.z);
             const dist = startVec.distanceTo(activeEnd);
             infoText = `${formatValue(dist)}`;
             previewShape = <SimpleLine points={[startVec.setY(0.05), activeEnd.setY(0.05)]} color={DIMENSION_COLOR} lineWidth={2} />;
        }
    } else if (snapInfo) {
        if (snapInfo.type !== 'grid') infoText = snapInfo.type;
        else infoText = `${formatValue(cursorPos.x)}, ${formatValue(cursorPos.z)}`;
    }

    const ui = (
        <group>
            {drawPoints.map((p, i) => (
                <mesh key={i} position={[p.x, 0.05, p.z]}>
                    <sphereGeometry args={[0.05]} />
                    <meshBasicMaterial color="red" depthTest={false} />
                </mesh>
            ))}
            {previewShape}
            {snapInfo && <SnapIndicator position={snapInfo.position} type={snapInfo.type} snapEdge={snapInfo.snapEdge} />}
            {(infoText || (snapInfo && snapInfo.type !== 'grid')) && (
                 <CursorTooltip text={infoText || (snapInfo?.type || '')} position={activeEnd} type={snapInfo?.type} />
            )}
        </group>
    );

    return {
        handlers: { handlePointerDown, handlePointerUp, handleClick, handlePointerMove },
        ui
    };
};

const SceneContent: React.FC = () => {
    const { shapes, selectedIds, selectShape, deselectAll, setIsOrbitEnabled, isOrbitEnabled, tool } = useApp();
    const pushPull = usePushPullManager();
    const drawing = useDrawingLogic();

    const handleBackgroundClick = (e: ThreeEvent<MouseEvent>) => {
        // If clicking on empty space (and not capturing a drawing event), deselect
        if (tool === ToolType.SELECT && selectedIds.length > 0) {
            deselectAll();
        }
        drawing.handlers.handleClick(e);
    };

    return (
        <>
            <ambientLight intensity={0.5} />
            <directionalLight position={[10, 20, 10]} intensity={1} castShadow />
            <Environment preset="city" />
            <OrbitControls 
                makeDefault 
                enabled={isOrbitEnabled || (tool === ToolType.SELECT && !pushPull.isDragging)} 
