            {/* Invisible Plane for capturing events on the ground */}
            <mesh 
                rotation={[-Math.PI / 2, 0, 0]} 
                position={[0, -0.01, 0]} 
                visible={false}
                onClick={handleBackgroundClick}
                onPointerDown={drawing.handlers.handlePointerDown}
                onPointerUp={drawing.handlers.handlePointerUp}
                onPointerMove={(e) => {
                    drawing.handlers.handlePointerMove(e);
                    pushPull.handlePointerMove(e);
                }}
            >
                <planeGeometry args={[1000, 1000]} />
            </mesh>

            {shapes.map(shape => (
                <ShapeRenderer 
                    key={shape.id} 
