                    isSelected={selectedIds.includes(shape.id)} 
                    onSelect={(e) => {
                        e.stopPropagation();
                        selectShape(shape.id, e.shiftKey);
                    }}
                    pushPullState={pushPull.ppState}
                    pushPullHandlers={pushPull}
                    drawingHandlers={drawing.handlers}
                />
            ))}

            {drawing.ui}
        </>
    );
};

